use super::tests::oid;
use super::*;
use crate::DomainError;
use proptest::prelude::*;

// Real git 2.43.0 output, generated by `testdata/status.sh` (`sh status.sh testdata`) in
// temporary repos with `GIT_CONFIG_GLOBAL=/dev/null`, `GIT_CONFIG_NOSYSTEM=1` and fixed dates. The command
// is always
//
// ```sh
// git status --porcelain=v2 -z --branch --untracked-files=all
// ```
//
// that is, the arguments of [`STATUS_ARGS`], except where noted.

/// Branch `main` with upstream `origin/main` (+2 -1) and every kind of change: staged, in the
/// worktree, both, added, removed, renamed (also with a non-UTF-8 name), type and
/// mode change, `git add -N`, modified submodule, untracked with strange names.
const MIXED: &[u8] = include_bytes!("testdata/status-mixed.bin");
/// Merge with conflicts `UD`, `DU`, `AA`, `UU` on `main` without upstream.
const CONFLICT: &[u8] = include_bytes!("testdata/status-conflict.bin");
/// Detached HEAD on `HEAD~1` with a modified file.
const DETACHED: &[u8] = include_bytes!("testdata/status-detached.bin");
/// Repo just created with `git init`: only headers, `branch.oid (initial)`.
const EMPTY: &[u8] = include_bytes!("testdata/status-empty.bin");
/// Repo without commits with a staged file and an untracked one.
const EMPTY_FILE: &[u8] = include_bytes!("testdata/status-empty-file.bin");
/// Upstream configured but without the `refs/remotes/origin/main` ref: no `branch.ab`.
const UPSTREAM_GONE: &[u8] = include_bytes!("testdata/status-upstream-gone.bin");
/// Same command with `--ignored` added.
const IGNORED: &[u8] = include_bytes!("testdata/status-ignored.bin");
/// `git -c status.renames=copies status --porcelain=v2 -z --branch --untracked-files=all`.
const COPIES: &[u8] = include_bytes!("testdata/status-copies.bin");

fn zero() -> Oid {
    Oid::from_bytes([0; 20])
}

fn parse(input: &[u8]) -> Status {
    parse_status(input).expect("valid real output")
}

fn reason(err: DomainError) -> String {
    match err {
        DomainError::InvalidGitOutput { command, reason } => {
            assert_eq!(command, "status");
            reason
        }
        other => panic!("unexpected error: {other:?}"),
    }
}

fn entry<'a>(status: &'a Status, path: &[u8]) -> &'a StatusEntry {
    status
        .entries
        .iter()
        .find(|e| e.path.as_bytes() == path)
        .unwrap_or_else(|| panic!("missing {}", String::from_utf8_lossy(path)))
}

fn xy(e: &StatusEntry) -> String {
    format!("{}{}", e.index.letter(), e.worktree.letter())
}

#[test]
fn mixed_head_and_upstream() {
    let s = parse(MIXED);
    assert_eq!(
        s.head,
        Head::Branch {
            name: "main".into(),
            target: Some(oid("20c3cb92d73084058a27dce4bd31368e91e68a63")),
        }
    );
    assert_eq!(
        s.upstream,
        Some(Upstream {
            name: "origin/main".into(),
            ahead: Some(2),
            behind: Some(1),
        })
    );
    assert_eq!(s.operation, None);
    assert!(!s.is_clean());
    assert!(!s.has_conflicts());
}

#[test]
fn mixed_xy_codes_in_order() {
    let s = parse(MIXED);
    let got: Vec<(String, String)> = s
        .entries
        .iter()
        .map(|e| (xy(e), e.path.to_string()))
        .collect();
    let want: Vec<(String, String)> = [
        ("A.", "added.txt"),
        ("MM", "both.txt"),
        (".M", "executable.sh"),
        ("M.", "in-stage.txt"),
        (".A", "intent.txt"),
        (".T", "kind.txt"),
        (".M", "modified.txt"),
        (".M", "module"),
        ("R.", "new-name.txt"),
        ("R.", "new-\u{fffd}.txt"),
        (".D", "removed-wt.txt"),
        ("D.", "removed.txt"),
        (".M", "with space.txt"),
        ("??", "a\nbreak.txt"),
        ("??", "folder/inner/deep.txt"),
        ("??", "non-utf8-\u{fffd}.txt"),
    ]
    .iter()
    .map(|(a, b)| ((*a).to_owned(), (*b).to_owned()))
    .collect();
    assert_eq!(got, want);
}

#[test]
fn staged_and_in_the_worktree() {
    let s = parse(MIXED);
    let staged: Vec<String> = s
        .entries
        .iter()
        .filter(|e| e.is_staged())
        .map(|e| e.path.to_string())
        .collect();
    assert_eq!(
        staged,
        [
            "added.txt",
            "both.txt",
            "in-stage.txt",
            "new-name.txt",
            "new-\u{fffd}.txt",
            "removed.txt",
        ]
    );
    let unstaged: Vec<String> = s
        .entries
        .iter()
        .filter(|e| e.is_unstaged())
        .map(|e| e.path.to_string())
        .collect();
    assert_eq!(
        unstaged,
        [
            "both.txt",
            "executable.sh",
            "intent.txt",
            "kind.txt",
            "modified.txt",
            "module",
            "removed-wt.txt",
            "with space.txt",
        ]
    );
}

#[test]
fn modified_file_with_modes_and_ids() {
    let s = parse(MIXED);
    let e = entry(&s, b"both.txt");
    assert_eq!((e.index, e.worktree), (Change::Modified, Change::Modified));
    assert_eq!(
        e.kind,
        EntryKind::Ordinary(TrackedInfo {
            submodule: None,
            mode_head: 0o100644,
            mode_index: 0o100644,
            mode_worktree: 0o100644,
            oid_head: oid("0358e43df179b7cd661bb2b8b9f6d61dafd87594"),
            oid_index: oid("299f8982a50a800c9fc6447eb4c3e6bf94b219cd"),
        })
    );
    // Execute bit: only the mode changes in the worktree.
    let EntryKind::Ordinary(info) = &entry(&s, b"executable.sh").kind else {
        panic!("ordinary entry expected");
    };
    assert_eq!((info.mode_index, info.mode_worktree), (0o100644, 0o100755));
    // From file to symbolic link.
    let e = entry(&s, b"kind.txt");
    assert_eq!(e.worktree, Change::TypeChanged);
    let EntryKind::Ordinary(info) = &e.kind else {
        panic!("ordinary entry expected");
    };
    assert_eq!(info.mode_worktree, 0o120000);
}

#[test]
fn added_and_removed_have_zero_ids() {
    let s = parse(MIXED);
    let EntryKind::Ordinary(added) = &entry(&s, b"added.txt").kind else {
        panic!("ordinary entry expected");
    };
    assert_eq!((added.mode_head, added.oid_head), (0, zero()));
    let EntryKind::Ordinary(deleted) = &entry(&s, b"removed.txt").kind else {
        panic!("ordinary entry expected");
    };
    assert_eq!((deleted.mode_index, deleted.oid_index), (0, zero()));
    // `git add -N`: the index has an empty entry, hence `.A`.
    let e = entry(&s, b"intent.txt");
    assert_eq!((e.index, e.worktree), (Change::Unmodified, Change::Added));
}

#[test]
fn renames_with_original_path() {
    let s = parse(MIXED);
    let e = entry(&s, b"new-name.txt");
    assert_eq!(e.index, Change::Renamed);
    assert_eq!(e.original_path(), Some(&RepoPath::from("old-name.txt")));
    let EntryKind::Renamed { score, .. } = e.kind else {
        panic!("rename expected");
    };
    assert_eq!(score, 100);
}

#[test]
fn non_utf8_paths_keep_their_bytes() {
    let s = parse(MIXED);
    let e = entry(&s, b"new-\xe9.txt");
    assert_eq!(
        e.original_path().map(RepoPath::as_bytes),
        Some(&b"old-\xe9.txt"[..])
    );
    assert_eq!(e.path.to_str(), None);
    assert_eq!(e.path.to_string_lossy(), "new-\u{fffd}.txt");
    let e = entry(&s, b"non-utf8-\xff.txt");
    assert!(e.is_untracked());
    // Spaces and newlines in the name: with `-z` git does not quote them.
    assert!(entry(&s, b"with space.txt").is_unstaged());
    assert!(entry(&s, b"a\nbreak.txt").is_untracked());
}

#[test]
fn untracked_also_in_new_folders() {
    let s = parse(MIXED);
    let e = entry(&s, b"folder/inner/deep.txt");
    assert_eq!(e.kind, EntryKind::Untracked);
    assert_eq!(
        (e.index, e.worktree),
        (Change::Untracked, Change::Untracked)
    );
    assert_eq!(e.path.file_name(), b"deep.txt");
    assert!(!e.is_staged() && !e.is_unstaged());
}

#[test]
fn modified_submodule() {
    let s = parse(MIXED);
    let e = entry(&s, b"module");
    assert_eq!(
        e.submodule(),
        Some(SubmoduleStatus {
            commit_changed: false,
            modified: true,
            untracked: true,
        })
    );
    assert_eq!(entry(&s, b"modified.txt").submodule(), None);
}

#[test]
fn merge_conflicts() {
    let s = parse(CONFLICT);
    assert_eq!(s.upstream, None);
    assert!(s.has_conflicts());
    let conflicts: Vec<(String, Conflict)> = s
        .entries
        .iter()
        .filter_map(|e| match &e.kind {
            EntryKind::Unmerged(u) => Some((e.path.to_string(), u.conflict)),
            _ => None,
        })
        .collect();
    assert_eq!(
        conflicts,
        [
            ("both-added.txt".into(), Conflict::BothAdded),
            ("both-modified.txt".into(), Conflict::BothModified),
            ("removed-by-them.txt".into(), Conflict::DeletedByThem),
            ("removed-by-us.txt".into(), Conflict::DeletedByUs),
        ]
    );
    let e = entry(&s, b"both-added.txt");
    assert!(e.is_conflict() && !e.is_staged() && !e.is_unstaged());
    assert_eq!((e.index, e.worktree), (Change::Added, Change::Added));
    let EntryKind::Unmerged(u) = &e.kind else {
        panic!("conflict expected");
    };
    // Added by both: no base.
    assert_eq!((u.mode_base, u.oid_base), (0, zero()));
    assert_eq!(u.oid_ours, oid("ba2906d0666cf726c7eaadd2cd3db615dedfdf3a"));
    assert_eq!(
        u.oid_theirs,
        oid("2299c37978265a95cbe835a4b0f0bbf15aad5549")
    );
    assert!(entry(&s, b"clean.txt").is_untracked());
}

#[test]
fn detached_head() {
    let s = parse(DETACHED);
    assert_eq!(
        s.head,
        Head::Detached(oid("43ebbc2025ec9ff97eceec32fae6c84d64a014f6"))
    );
    assert_eq!(s.upstream, None);
    assert_eq!(s.entries.len(), 1);
    assert!(entry(&s, b"file.txt").is_unstaged());
}

#[test]
fn empty_repo() {
    let s = parse(EMPTY);
    assert_eq!(
        s,
        Status {
            head: Head::Branch {
                name: "main".into(),
                target: None,
            },
            upstream: None,
            entries: Vec::new(),
            operation: None,
        }
    );
    assert!(s.is_clean());

    let s = parse(EMPTY_FILE);
    assert_eq!(s.head.target(), None);
    assert!(entry(&s, b"new.txt").is_staged());
    assert!(entry(&s, b"loose.txt").is_untracked());
}

#[test]
fn upstream_gone_without_ahead_behind() {
    let s = parse(UPSTREAM_GONE);
    assert_eq!(
        s.upstream,
        Some(Upstream {
            name: "origin/main".into(),
            ahead: None,
            behind: None,
        })
    );
    assert!(s.is_clean());
}

#[test]
fn ignored() {
    let s = parse(IGNORED);
    let kinds: Vec<(String, EntryKind)> = s
        .entries
        .iter()
        .map(|e| (e.path.to_string(), e.kind.clone()))
        .collect();
    assert_eq!(
        kinds,
        [
            ("loose.txt".into(), EntryKind::Untracked),
            ("build/out.o".into(), EntryKind::Ignored),
            ("debug.log".into(), EntryKind::Ignored),
        ]
    );
    assert_eq!(xy(&s.entries[2]), "!!");
}

#[test]
fn copies() {
    let s = parse(COPIES);
    let e = entry(&s, b"copy.txt");
    assert_eq!(e.index, Change::Copied);
    let EntryKind::Copied {
        original, score, ..
    } = &e.kind
    else {
        panic!("copy expected");
    };
    assert_eq!((original, *score), (&RepoPath::from("originale.txt"), 100));
    assert!(e.is_staged());
}

#[test]
fn unknown_headers_ignored() {
    let mut input = b"# stash 3\0# futuro\0".to_vec();
    input.extend_from_slice(DETACHED);
    assert_eq!(parse_status(&input), Ok(parse(DETACHED)));
}

#[test]
fn args() {
    assert_eq!(
        STATUS_ARGS,
        ["--porcelain=v2", "-z", "--branch", "--untracked-files=all"]
    );
}

#[test]
fn status_json() {
    let s = parse(MIXED);
    let json = serde_json::to_value(&s).expect("serializzabile");
    assert_eq!(json["upstream"]["ahead"], 2);
    // UTF-8 paths are strings, the others byte arrays.
    let paths: Vec<&serde_json::Value> = json["entries"]
        .as_array()
        .expect("array")
        .iter()
        .map(|e| &e["path"])
        .collect();
    assert_eq!(paths[0], "added.txt");
    let non_utf8 = paths
        .iter()
        .find(|p| p.is_array())
        .expect("at least one non-UTF-8 path");
    let bytes: Vec<u8> = serde_json::from_value((*non_utf8).clone()).expect("byte");
    assert_eq!(bytes, b"new-\xe9.txt");
    let back: Status = serde_json::from_value(json).expect("deserializzabile");
    assert_eq!(back, s);
}

// --- Malformed inputs -------------------------------------------------------------------

/// The two headers of [`DETACHED`] followed by `record` and the final NUL.
fn with_record(record: &[u8]) -> Vec<u8> {
    let mut input = b"# branch.oid 43ebbc2025ec9ff97eceec32fae6c84d64a014f6\0\
                      # branch.head main\0"
        .to_vec();
    input.extend_from_slice(record);
    input.push(0);
    input
}

fn err_of(input: &[u8]) -> String {
    reason(parse_status(input).unwrap_err())
}

#[test]
fn error_without_headers() {
    assert!(err_of(b"").contains("missing header `# branch.oid`"));
    let r = err_of(b"? a.txt\0");
    assert!(r.contains("`--branch`"), "{r}");
    let r = err_of(b"# branch.oid (initial)\0");
    assert!(r.contains("`# branch.head`"), "{r}");
}

#[test]
fn error_if_the_final_nul_is_missing() {
    let input = &DETACHED[..DETACHED.len() - 1];
    assert!(err_of(input).contains("does not end with NUL"));
}

#[test]
fn error_on_invalid_headers() {
    let cases_list: [(&[u8], &str); 7] = [
        (
            b"# branch.oid 1234\0# branch.head main\0",
            "is not a valid id",
        ),
        (
            b"# branch.oid (initial)\0# branch.head (detached)\0",
            "detached HEAD",
        ),
        (
            b"# branch.oid (initial)\0# branch.head\0",
            "without branch name",
        ),
        (
            b"# branch.oid (initial)\0# branch.head main\0# branch.ab +1 -2\0",
            "without `branch.upstream`",
        ),
        (
            b"# branch.oid (initial)\0# branch.head main\0# branch.upstream o/m\0# branch.ab 1 2\0",
            "invalid `branch.ab 1 2`",
        ),
        (
            b"# branch.oid (initial)\0# branch.head main\0# branch.upstream o/m\0# branch.ab +1\0",
            "invalid",
        ),
        (
            b"# branch.oid (initial)\0# branch.head a\0# branch.head b\0",
            "repeated header",
        ),
    ];
    for (input, expected_msg) in cases_list {
        let r = err_of(input);
        assert!(
            r.contains(expected_msg),
            "{:?}: {r}",
            String::from_utf8_lossy(input)
        );
    }
}

#[test]
fn error_on_invalid_entries() {
    let h = "43ebbc2025ec9ff97eceec32fae6c84d64a014f6";
    let ord = |xy: &str, sub: &str, mode: &str, id: &str, path: &str| {
        format!("1 {xy} {sub} 100644 {mode} 100644 {h} {id} {path}")
    };
    let cases_list: Vec<(Vec<u8>, &str)> = vec![
        (ord("XY", "N...", "100644", h, "a").into(), "XY code"),
        (ord("M", "N...", "100644", h, "a").into(), "XY code"),
        (
            ord(".M", "S?..", "100644", h, "a").into(),
            "submodule status",
        ),
        (ord(".M", "N...", "100648", h, "a").into(), "octal mode"),
        (
            ord(".M", "N...", "100644", "zz", "a").into(),
            "id in the index",
        ),
        (
            format!("1 .M N... 100644 100644 100644 {h} {h}").into(),
            "7 fields instead of 8",
        ),
        (
            format!("1 .M N... 100644 100644 100644 {h} {h} ").into(),
            "empty path",
        ),
        (b"? ".to_vec(), "empty path"),
        (b"x a.txt".to_vec(), "unknown record type `x`"),
        (b"?a.txt".to_vec(), "is not a valid record"),
        (Vec::new(), "empty record"),
        (
            format!("u MM N... 100644 100644 100644 100644 {h} {h} {h} a").into(),
            "is not a conflict status",
        ),
        (
            format!("2 R. N... 100644 100644 100644 {h} {h} X100 new\0old").into(),
            "rename score",
        ),
        (
            format!("2 R. N... 100644 100644 100644 {h} {h} R101 new\0old").into(),
            "from 0 to 100",
        ),
        (
            format!("2 R. N... 100644 100644 100644 {h} {h} R90 new\0").into(),
            "original path: empty path",
        ),
    ];
    for (record, expected_msg) in cases_list {
        let r = err_of(&with_record(&record));
        assert!(r.contains("record 3"), "{r}");
        assert!(
            r.contains(expected_msg),
            "{:?}: {r}",
            String::from_utf8_lossy(&record)
        );
    }
    // The original path of the rename is missing altogether: the output ends after the new one.
    let mut input =
        with_record(format!("2 R. N... 100644 100644 100644 {h} {h} R90 new").as_bytes());
    let r = err_of(&input);
    assert!(r.contains("missing original path"), "{r}");
    input.extend_from_slice(b"old\0");
    assert!(parse_status(&input).is_ok());
}

// --- Properties --------------------------------------------------------------------------

/// Writes a status as git would with [`STATUS_ARGS`] (and `--ignored`).
fn render(s: &Status) -> Vec<u8> {
    let mut out = Vec::new();
    let mut rec = |parts: &[&[u8]]| {
        for p in parts {
            out.extend_from_slice(p);
        }
        out.push(0);
    };
    let oid_text = match s.head.target() {
        Some(o) => o.to_string(),
        None => "(initial)".to_owned(),
    };
    rec(&[b"# branch.oid ", oid_text.as_bytes()]);
    let name = match &s.head {
        Head::Branch { name, .. } => name.clone(),
        Head::Detached(_) => "(detached)".to_owned(),
    };
    rec(&[b"# branch.head ", name.as_bytes()]);
    if let Some(u) = &s.upstream {
        rec(&[b"# branch.upstream ", u.name.as_bytes()]);
        if let (Some(a), Some(b)) = (u.ahead, u.behind) {
            rec(&[format!("# branch.ab +{a} -{b}").as_bytes()]);
        }
    }
    let sub = |s: Option<SubmoduleStatus>| match s {
        None => "N...".to_owned(),
        Some(s) => format!(
            "S{}{}{}",
            if s.commit_changed { 'C' } else { '.' },
            if s.modified { 'M' } else { '.' },
            if s.untracked { 'U' } else { '.' }
        ),
    };
    let tracked = |i: &TrackedInfo| {
        format!(
            "{} {:06o} {:06o} {:06o} {} {}",
            sub(i.submodule),
            i.mode_head,
            i.mode_index,
            i.mode_worktree,
            i.oid_head,
            i.oid_index
        )
    };
    for e in &s.entries {
        let xy = format!("{}{}", e.index.letter(), e.worktree.letter());
        let path = e.path.as_bytes();
        match &e.kind {
            EntryKind::Ordinary(i) => {
                rec(&[format!("1 {xy} {} ", tracked(i)).as_bytes(), path]);
            }
            EntryKind::Renamed {
                info,
                original,
                score,
            }
            | EntryKind::Copied {
                info,
                original,
                score,
            } => {
                let letter = if matches!(e.kind, EntryKind::Copied { .. }) {
                    'C'
                } else {
                    'R'
                };
                rec(&[
                    format!("2 {xy} {} {letter}{score} ", tracked(info)).as_bytes(),
                    path,
                ]);
                rec(&[original.as_bytes()]);
            }
            EntryKind::Unmerged(u) => rec(&[
                format!(
                    "u {xy} {} {:06o} {:06o} {:06o} {:06o} {} {} {} ",
                    sub(u.submodule),
                    u.mode_base,
                    u.mode_ours,
                    u.mode_theirs,
                    u.mode_worktree,
                    u.oid_base,
                    u.oid_ours,
                    u.oid_theirs
                )
                .as_bytes(),
                path,
            ]),
            EntryKind::Untracked => rec(&[b"? ", path]),
            EntryKind::Ignored => rec(&[b"! ", path]),
        }
    }
    out
}

fn arb_oid() -> impl Strategy<Value = Oid> {
    any::<[u8; 20]>().prop_map(Oid::from_bytes)
}

/// Any bytes except NUL, at least one: a valid path for git with `-z`.
fn arb_path() -> impl Strategy<Value = RepoPath> {
    prop::collection::vec(1u8..=255, 1..20).prop_map(RepoPath::from)
}

fn arb_change() -> impl Strategy<Value = Change> {
    prop::sample::select(vec![
        Change::Unmodified,
        Change::Modified,
        Change::TypeChanged,
        Change::Added,
        Change::Deleted,
        Change::Renamed,
        Change::Copied,
    ])
}

fn arb_sub() -> impl Strategy<Value = Option<SubmoduleStatus>> {
    prop::option::of(
        any::<(bool, bool, bool)>().prop_map(|(c, m, u)| SubmoduleStatus {
            commit_changed: c,
            modified: m,
            untracked: u,
        }),
    )
}

fn arb_mode() -> impl Strategy<Value = u32> {
    prop::sample::select(vec![0, 0o100644, 0o100755, 0o120000, 0o160000])
}

fn arb_tracked() -> impl Strategy<Value = TrackedInfo> {
    (
        arb_sub(),
        arb_mode(),
        arb_mode(),
        arb_mode(),
        arb_oid(),
        arb_oid(),
    )
        .prop_map(|(submodule, mh, mi, mw, oh, oi)| TrackedInfo {
            submodule,
            mode_head: mh,
            mode_index: mi,
            mode_worktree: mw,
            oid_head: oh,
            oid_index: oi,
        })
}

fn arb_conflict() -> impl Strategy<Value = (Conflict, Change, Change)> {
    use Change::{Added as A, Deleted as D, Unmerged as U};
    prop::sample::select(vec![
        (Conflict::BothDeleted, D, D),
        (Conflict::AddedByUs, A, U),
        (Conflict::DeletedByThem, U, D),
        (Conflict::AddedByThem, U, A),
        (Conflict::DeletedByUs, D, U),
        (Conflict::BothAdded, A, A),
        (Conflict::BothModified, U, U),
    ])
}

fn arb_entry() -> impl Strategy<Value = StatusEntry> {
    let tracked = (arb_path(), arb_change(), arb_change(), arb_tracked()).prop_map(
        |(path, index, worktree, info)| StatusEntry {
            path,
            index,
            worktree,
            kind: EntryKind::Ordinary(info),
        },
    );
    let moved = (
        arb_path(),
        arb_change(),
        arb_tracked(),
        arb_path(),
        0u8..=100,
        any::<bool>(),
    )
        .prop_map(|(path, worktree, info, original, score, copy)| {
            let (index, kind) = if copy {
                (
                    Change::Copied,
                    EntryKind::Copied {
                        info,
                        original,
                        score,
                    },
                )
            } else {
                (
                    Change::Renamed,
                    EntryKind::Renamed {
                        info,
                        original,
                        score,
                    },
                )
            };
            StatusEntry {
                path,
                index,
                worktree,
                kind,
            }
        });
    let unmerged = (
        arb_path(),
        arb_conflict(),
        arb_sub(),
        (arb_mode(), arb_mode(), arb_mode(), arb_mode()),
        (arb_oid(), arb_oid(), arb_oid()),
    )
        .prop_map(
            |(path, (conflict, index, worktree), submodule, (m1, m2, m3, mw), (h1, h2, h3))| {
                StatusEntry {
                    path,
                    index,
                    worktree,
                    kind: EntryKind::Unmerged(UnmergedInfo {
                        conflict,
                        submodule,
                        mode_base: m1,
                        mode_ours: m2,
                        mode_theirs: m3,
                        mode_worktree: mw,
                        oid_base: h1,
                        oid_ours: h2,
                        oid_theirs: h3,
                    }),
                }
            },
        );
    let simple = (arb_path(), any::<bool>()).prop_map(|(path, ignored)| {
        let (change, kind) = if ignored {
            (Change::Ignored, EntryKind::Ignored)
        } else {
            (Change::Untracked, EntryKind::Untracked)
        };
        StatusEntry {
            path,
            index: change,
            worktree: change,
            kind,
        }
    });
    prop_oneof![tracked, moved, unmerged, simple]
}

fn arb_head() -> impl Strategy<Value = Head> {
    prop_oneof![
        ("[a-z][a-z/._-]{0,15}", prop::option::of(arb_oid()))
            .prop_map(|(name, target)| Head::Branch { name, target }),
        arb_oid().prop_map(Head::Detached),
    ]
}

fn arb_upstream() -> impl Strategy<Value = Option<Upstream>> {
    prop::option::of(
        (
            "[a-z][a-z/]{0,15}",
            prop::option::of((any::<u32>(), any::<u32>())),
        )
            .prop_map(|(name, ab)| Upstream {
                name,
                ahead: ab.map(|(a, _)| a),
                behind: ab.map(|(_, b)| b),
            }),
    )
}

fn arb_status() -> impl Strategy<Value = Status> {
    (
        arb_head(),
        arb_upstream(),
        prop::collection::vec(arb_entry(), 0..6),
    )
        .prop_map(|(head, upstream, entries)| Status {
            head,
            upstream,
            entries,
            operation: None,
        })
}

proptest! {
    #[test]
    fn round_trip_of_the_format(status in arb_status()) {
        let parsed = parse_status(&render(&status))
            .map_err(|e| TestCaseError::fail(e.to_string()))?;
        prop_assert_eq!(parsed, status);
    }

    #[test]
    fn round_trip_json(status in arb_status()) {
        let json = serde_json::to_string(&status).map_err(|e| TestCaseError::fail(e.to_string()))?;
        let back: Status = serde_json::from_str(&json).map_err(|e| TestCaseError::fail(e.to_string()))?;
        prop_assert_eq!(back, status);
    }

    #[test]
    fn no_panic_on_arbitrary_bytes(input in prop::collection::vec(any::<u8>(), 0..400)) {
        let _ = parse_status(&input);
    }

    #[test]
    fn no_panic_on_altered_real_output(pos in 0..MIXED.len(), byte in any::<u8>()) {
        let mut input = MIXED.to_vec();
        input[pos] = byte;
        let _ = parse_status(&input);
    }

    #[test]
    fn no_panic_on_truncated_real_output(len in 0..MIXED.len()) {
        let _ = parse_status(&MIXED[..len]);
    }
}
